1	//! Content-based format detection. NEVER trusts file extensions.
2	//!
3	//! Order: magic bytes → binary check → text heuristics
4	//! (json/jsonl → html/xml → logs → sql dump → csv → yaml → txt).
5	
6	use anyhow::Result;
7	use std::io::Read;
8	use std::path::Path;
9	
10	#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
11	pub enum Family {
12	    Jsonl,
13	    Json,
14	    Csv,
15	    Logs,
16	    Xml,
17	    Html,
18	    Yaml,
19	    TxtProse,
20	    TxtLines,
21	    Pdf,
22	    /// RFC 5322 / MIME email message (`.eml`, `message/rfc822`): headers parsed
23	    /// into fields, MIME decoded, and each attachment indexed as its own
24	    /// document (PDFs routed to the PDF extractor).
25	    Eml,
26	    /// mbox mailbox: many RFC 5322 messages in one file, each opened by a
27	    /// `From <sender> <date>` separator line (Google Takeout, Thunderbird,
28	    /// Apple Mail, mutt). Split as a STREAM — multi-GB is the normal size — and
29	    /// each message goes through the same extraction as [`Family::Eml`].
30	    Mbox,
31	    Docx,
32	    Sqlite,
33	    SqlDump,
34	    /// Source code — AST-parsed by the matching tree-sitter grammar.
35	    Code,
36	    /// Unity text-serialized asset (scene/prefab/.asset/.mat/.anim/…):
37	    /// a `%YAML` + `%TAG !u! tag:unity3d.com` multi-document stream.
38	    UnityYaml,
39	    /// Unity `.meta` sidecar: plain YAML opening with `fileFormatVersion:`
40	    /// and carrying the asset `guid` — the join key for everything Unity.
41	    UnityMeta,
42	    /// Biovision motion capture: a skeleton HIERARCHY header followed by a
43	    /// large numeric MOTION block. Indexed as ONE metadata record per file
44	    /// (joints, frame count, duration) — the motion numbers are never read.
45	    Bvh,
46	    /// User-designated existence-only file (`--stub <glob>`): ONE name-card
47	    /// record, contents never opened. For corpus-specific data blobs the
48	    /// owner wants referenceable but not parsed — never assigned by
49	    /// sniffing, only by the CLI flag.
50	    Stub,
51	    Binary,
52	}
53	
54	impl Family {
55	    pub fn as_str(&self) -> &'static str {
56	        match self {
57	            Family::Jsonl => "jsonl",
58	            Family::Json => "json",
59	            Family::Csv => "csv",
60	            Family::Logs => "logs",
61	            Family::Xml => "xml",
62	            Family::Html => "html",
63	            Family::Yaml => "yaml",
64	            Family::TxtProse => "txt-prose",
65	            Family::TxtLines => "txt-lines",
66	            Family::Pdf => "pdf",
67	            Family::Eml => "eml",
68	            Family::Mbox => "mbox",
69	            Family::Docx => "docx",
70	            Family::Sqlite => "sqlite",
71	            Family::SqlDump => "sqldump",
72	            Family::Code => "code",
73	            Family::UnityYaml => "unity",
74	            Family::UnityMeta => "unity-meta",
75	            Family::Bvh => "bvh",
76	            Family::Stub => "stub",
77	            Family::Binary => "binary",
78	        }
79	    }
80	    /// Document-family formats produce one record per document/section.
81	    pub fn is_document(&self) -> bool {
82	        matches!(
83	            self,
84	            Family::Pdf | Family::Docx | Family::TxtProse | Family::Eml | Family::Mbox
85	        )
86	    }
87	}
