89	#[derive(Debug, Clone, Copy)]
90	pub struct CsvDialect {
91	    pub delim: u8,
92	    pub has_header: bool,
93	    pub decimal_comma: bool,
94	}
95	
96	#[derive(Debug, Clone)]
97	pub struct Sniffed {
98	    pub family: Family,
99	    pub gzip: bool,
100	    /// e.g. "png", "zip", "elf", "unknown" — set when family == Binary.
101	    pub binary_kind: Option<String>,
102	    pub csv: Option<CsvDialect>,
103	    /// "utf-8" or "windows-1252 (lossy)"
104	    pub encoding: &'static str,
105	    /// File name of the LOGICAL source (`app.py`), even when the sniffed
106	    /// content lives elsewhere. Durable preparation reads content-addressed
107	    /// snapshot blobs (`blobs/00000000`), so an extractor that recovers a
108	    /// parameter from its content path silently loses the name — that is how
109	    /// #294 turned every code file into junk. Name-derived decisions after
110	    /// sniffing must use this, never the content path.
111	    pub logical_name: Option<std::path::PathBuf>,
112	}
113	
114	/// Bytes read for ordinary classification.
115	const PREFIX: usize = 8192;
116	
117	/// Bytes read when the file already carries GIF magic. A Comment Extension is
118	/// unbounded by the format, so this is a budget rather than a guarantee: it
119	/// covers every commented GIF in the measured corpus with room to spare.
120	///
121	/// The value is load-bearing, and in the direction that is easy to get
122	/// backwards. `read_prefix` returns `min(file_size, GIF_PREFIX)`, so the buffer
123	/// is full exactly when the file is at least this large — and a full buffer is
124	/// the answer "image" (see the `None` arm of the comment walk). LOWERING the
125	/// budget therefore admits MORE files, not fewer: at 128 KiB every text file
126	/// over 128 KiB carrying the header shape is called an image, where at 1 MiB
127	/// only those over 1 MiB are — **by this path**. Raising it costs a larger read
128	/// per GIF candidate and narrows that window.
129	///
130	/// This budget is not the whole rule, and reading it as such is the mistake to
131	/// avoid when deciding whether to change it. The arm is `full || canvas`: the
132	/// canvas disjunct admits text of ANY size, so no value of this constant closes
133	/// that window. `the_canvas_path_junks_prose_at_any_size_and_the_budget_does_not_bound_it`
134	/// pins a 3,000-byte prose file called an image at a 1 MiB budget. Pinned by
135	/// `the_budget_is_the_threshold_it_claims`, which measures this path only.
136	const GIF_PREFIX: usize = 1 << 20;
137	
138	fn read_prefix(path: &Path, gzip: bool, n: usize) -> Result<Vec<u8>> {
139	    let f = std::fs::File::open(path)?;
140	    let mut buf = Vec::with_capacity(n.min(1 << 20));
141	    if gzip {
142	        let mut r = flate2::read::MultiGzDecoder::new(f).take(n as u64);
143	        r.read_to_end(&mut buf).ok(); // truncated gz prefix is fine for sniffing
144	    } else {
145	        let mut r = f.take(n as u64);
146	        r.read_to_end(&mut buf)?;
147	    }
148	    Ok(buf)
149	}
150	
151	pub fn sniff(path: &Path) -> Result<Sniffed> {
152	    sniff_with_name(path, path)
153	}
154	
155	/// Classify bytes from `content_path` while retaining the logical filename
156	/// signals (currently source-code extensions) from `logical_path`.
157	///
158	/// Durable preparation uses this to classify an immutable snapshot blob
159	/// without losing the original name merely because the blob itself is named
160	/// by an ordinal.
161	pub fn sniff_with_name(content_path: &Path, logical_path: &Path) -> Result<Sniffed> {
162	    let head = read_prefix(content_path, false, 8)?;
163	    let gzip = head.len() >= 2 && head[0] == 0x1f && head[1] == 0x8b;
164	    let mut prefix = read_prefix(content_path, gzip, PREFIX)?;
165	    // A GIF's first data block can sit arbitrarily far in — a Comment
166	    // Extension is a chain of 1..=255-byte sub-blocks with no length bound,
167	    // and real files carry licence notices of tens of kilobytes. Deciding
168	    // whether such a file is an image from 8 KiB means deciding it before its
169	    // structure is visible, and four successive attempts to guess that from
170	    // bytes inside the window were each refuted for junking real images
171	    // (#379): a rule keyed on any fixed offset reads unconstrained image data
172	    // there. So read further for a GIF candidate instead of guessing — the
173	    // chain's terminator then falls inside the buffer and the decisive check
174	    // applies. One extra read, only for files already carrying GIF magic.
175	    if prefix.len() == PREFIX && prefix.len() >= 6 && matches!(&prefix[..6], b"GIF87a" | b"GIF89a")
176	    {
177	        prefix = read_prefix(content_path, gzip, GIF_PREFIX)?;
178	    }
179	    let mut s = sniff_bytes(&prefix, content_path, logical_path, gzip)?;
180	    s.gzip = gzip;
181	    s.logical_name = logical_path.file_name().map(std::path::PathBuf::from);
182	    Ok(s)
183	}
184	
185	fn sniff_bytes(
186	    prefix: &[u8],
187	    content_path: &Path,
188	    logical_path: &Path,
189	    gzip: bool,
190	) -> Result<Sniffed> {
191	    let mk = |family: Family| Sniffed {
192	        family,
193	        gzip: false,
194	        binary_kind: None,
195	        csv: None,
196	        encoding: "utf-8",
197	        logical_name: None,
198	    };
199	    if prefix.is_empty() {
200	        let mut s = mk(Family::Binary);
201	        s.binary_kind = Some("empty".into());
202	        return Ok(s);
203	    }
204	
205	    // 1. Magic bytes.
206	    //
207	    // %PDF- stays here rather than in MAGIC_TABLE (#403's own fix sketch
208	    // floated moving it): every MAGIC_TABLE row reports `Family::Binary` +
209	    // a `binary_kind` string, but %PDF- has to report the distinct
210	    // `Family::Pdf` the extractor routes on (lib.rs:1229) — widening the
211	    // shared `MagicRow` type for the one row that needs a different Family
212	    // is a bigger, riskier change than this bug needs. `pdf_header` gives it
213	    // the same structural qualifier the table's own rows carry; see its doc
214	    // comment for what it rejects.
215	    if prefix.starts_with(b"%PDF-") && pdf_header(prefix) {
216	        return Ok(mk(Family::Pdf));
217	    }
218	    if prefix.starts_with(b"SQLite format 3\0") {
219	        return Ok(mk(Family::Sqlite));
220	    }
221	    if prefix.starts_with(b"PK\x03\x04") {
222	        // zip container: DOCX iff it holds word/document.xml
223	        if !gzip {
224	            if let Ok(f) = std::fs::File::open(content_path) {
225	                if let Ok(mut z) = zip::ZipArchive::new(f) {
226	                    let is_docx = (0..z.len()).any(|i| {
227	                        z.by_index_raw(i)
228	                            .map(|e| e.name() == "word/document.xml")
229	                            .unwrap_or(false)
230	                    });
231	                    if is_docx {
232	                        return Ok(mk(Family::Docx));
233	                    }
234	                }
235	            }
236	        }
237	        let mut s = mk(Family::Binary);
238	        s.binary_kind = Some("zip".into());
239	        return Ok(s);
240	    }
241	    // Compressed image/audio/model payloads routinely pass the NUL and
242	    // control-char heuristics below (windows-1252 decodes almost every byte
243	    // to something printable), and a multi-MB PSD misread as prose turns into
244	    // thousands of junk records — measured: a 4,194,360-byte printable blob
245	    // yields 2,048 sections. `for_each_section` streams, so the cost is the
246	    // record COUNT, not resident bytes. Magic bytes are the reliable signal.
247	    // `MAGIC_TABLE` and its invariant are documented at the table itself.
248	    for &(magic, kind, qualify) in MAGIC_TABLE {
249	        if prefix.starts_with(magic) && qualify(prefix) {
250	            let mut s = mk(Family::Binary);
251	            s.binary_kind = Some(kind.into());
252	            return Ok(s);
253	        }
254	    }
255	    // Truevision TGA has NO magic number — the file opens straight into its
256	    // 18-byte header — so a raw texture is the one image format that reaches
257	    // the text heuristics on its own bytes. Its header is nevertheless highly
258	    // constrained, which is what makes this safe: byte 1 must be 0 or 1 and
259	    // byte 2 one of six small values, i.e. the second and third bytes of the
260	    // file must BOTH be control characters, which text is not.
261	    if looks_like_tga_header(prefix) {
262	        let mut s = mk(Family::Binary);
263	        s.binary_kind = Some("tga".into());
264	        return Ok(s);
265	    }
266	    // tar — reached for a `.tgz`/`.tar.gz` too, because `prefix` is already the
267	    // DECOMPRESSED stream. It would be junked as "unknown" by the NUL ratio
268	    // below anyway (a tar header is mostly NUL padding); this only names it, so
269	    // the run can tell the user what to do about it.
270	    if looks_like_tar_header(prefix) {
271	        let mut s = mk(Family::Binary);
272	        s.binary_kind = Some("tar".into());
273	        return Ok(s);
274	    }
275	
276	    // 2. Binary vs text: decode UTF-8, fall back windows-1252.
277	    let (text, encoding) = decode(prefix);
278	    let nul = prefix.iter().filter(|&&b| b == 0).count();
279	    if nul * 10 > prefix.len() {
280	        let mut s = mk(Family::Binary);
281	        s.binary_kind = Some("unknown".into());
282	        return Ok(s);
283	    }
284	    // High ratio of control chars (excluding \t \n \r) → binary.
285	    let ctrl = text
286	        .chars()
287	        .filter(|c| (*c as u32) < 0x20 && !matches!(c, '\t' | '\n' | '\r'))
288	        .count();
289	    if ctrl * 10 > text.chars().count().max(1) {
290	        let mut s = mk(Family::Binary);
291	        s.binary_kind = Some("unknown".into());
292	        return Ok(s);
293	    }
294	    // NOTE — a "decoded via lossy windows-1252 AND over 30% non-ASCII is
295	    // pixel soup" guard was here, to catch a raw TGA. It is gone, and must
296	    // not come back in that form: the windows-1252 fallback is what EVERY
297	    // legacy 8-bit codepage and every legacy CJK encoding decodes through, so
298	    // the test was not "is this an image", it was "is this written in a script
299	    // that is not Latin". Measured through `sniff()` against `ca4d75a` with
300	    // identical fixtures, it changed windows-1251 Russian, KOI8-R Russian,
301	    // windows-1253 Greek, windows-1255 Hebrew and windows-1256 Arabic prose
302	    // from `TxtProse` to `Binary`, and `scan_file` turns `Binary` into
303	    // "junk: binary content (unknown)" — the file is never indexed and the
304	    // report says only that something unreadable was skipped.
305	    //
306	    // A `looks_like_legacy_cjk` escape hatch was tried and could not carry the
307	    // weight, for two reasons worth recording so it is not retried:
308	    //   * single-byte codepages never form valid SHIFT_JIS/GBK/BIG5/EUC_KR
309	    //     double-byte pairs, so Cyrillic/Greek/Hebrew/Arabic were never
310	    //     rescued by it at all;
311	    //   * it required a LOSSLESS trial decode, and `sniff()` only ever sees
312	    //     `read_prefix(path, gzip, 8192)`. A double-byte character straddling
313	    //     that cut makes every trial decode report `had_errors`, so the same
314	    //     Shift-JIS document was text or binary depending on its byte length
315	    //     — measured `TxtProse` at pad 0 and 2, `Binary` at pad 1 and 3.
316	    //
317	    // TGA is now caught by its header above, which is evidence of pixel data
318	    // rather than evidence of a non-Latin script. Headerless raw payloads
319	    // (`.raw`, `.bytes`, uncompressed PCM) still classify as text, exactly as
320	    // they do on `main`. Bounding what a magic-less binary costs is the right
321	    // fix for that (issue #381 — sectioning already streams, so the unbounded
322	    // quantity is the record count), not byte statistics that cannot tell a
323	    // texture from Cyrillic.
324	
325	    // 2b. Unity text serialization, detected by content (never extension):
326	    // scenes/prefabs/assets open with `%YAML` and declare the Unity tag
327	    // namespace; `.meta` sidecars open with `fileFormatVersion:` and carry a
328	    // `guid:`. Binary-serialized Unity assets fail both checks and fall
329	    // through to the binary/text heuristics as before.
330	    {
331	        let body = text.trim_start_matches('\u{feff}');
332	        if body.starts_with("%YAML") && body.contains("%TAG !u! tag:unity3d.com") {
333	            let mut s = mk(Family::UnityYaml);
334	            s.encoding = encoding;
335	            return Ok(s);
336	        }
337	        let first_line = body.lines().next().unwrap_or("");
338	        if first_line.starts_with("fileFormatVersion:")
339	            && body.lines().any(|l| l.starts_with("guid:"))
340	        {
341	            let mut s = mk(Family::UnityMeta);
342	            s.encoding = encoding;
343	            return Ok(s);
344	        }
345	        // BVH motion capture: `HIERARCHY` opener with a `ROOT <name>` next.
346	        // Without this the numeric MOTION block classified as txt-lines and
347	        // indexed millions of meaningless number rows.
348	        if first_line.trim() == "HIERARCHY"
349	            && body
350	                .lines()
351	                .nth(1)
352	                .is_some_and(|l| l.trim_start().starts_with("ROOT "))
353	        {
354	            let mut s = mk(Family::Bvh);
355	            s.encoding = encoding;
356	            return Ok(s);
357	        }
358	    }
359	
360	    // 2c. Source code: a known code extension whose content is text. We only
361	    // reach here after the binary guards above, so a text `.py`/`.rs`/`.go`/…
362	    // routes to the tree-sitter AST extractor (crate::extract::code). Extension
363	    // is the right signal — code vs prose is not reliably content-sniffable.
364	    if let Some(ext) = logical_path.extension().and_then(|e| e.to_str()) {
365	        if crate::extract::code::is_code_ext(ext) {
366	            let mut s = mk(Family::Code);
367	            s.encoding = encoding;
368	            return Ok(s);
369	        }
370	    }
371	
372	    // 3. Text heuristics — complete lines only (last line may be truncated).
373	    let mut lines: Vec<&str> = text.lines().collect();
374	    if !text.ends_with('\n') && lines.len() > 1 {
375	        lines.pop();
376	    }
377	    let nonblank: Vec<&str> = lines
378	        .iter()
379	        .copied()
380	        .filter(|l| !l.trim().is_empty())
381	        .collect();
382	
383	    let mut out = mk(classify_text(&text, &nonblank));
384	    out.encoding = encoding;
385	    if out.family == Family::Csv {
386	        out.csv = sniff_csv_dialect(&nonblank);
387	        if out.csv.is_none() {
388	            out.family = txt_kind(&nonblank);
389	        }
390	    }
391	    Ok(out)
392	}
393	
394	/// The label for the last-resort decode. Every byte maps to *something* in
395	/// windows-1252, so this never fails and therefore carries no evidence that
396	/// the bytes are text — the binary heuristics key off this exact string.
397	pub const WINDOWS_1252_LOSSY: &str = "windows-1252 (lossy)";
398	
399	/// A magic-byte row: the signature, the `binary_kind` it reports, and the
400	/// structural check that has to pass before the signature is believed.
401	type MagicRow = (&'static [u8], &'static str, fn(&[u8]) -> bool);
402	
403	/// Media/container signatures, tried in order before any text heuristic.
404	///
405	/// THE INVARIANT, and the reason this table is a named constant rather than a
406	/// literal inside `sniff_bytes`: **a signature whose bytes are all printable
407	/// ASCII MUST carry a qualifier**, because "starts with these letters" is also
408	/// true of ordinary text. A CSV whose first column header is `ID3` or `BMW`,
409	/// prose whose first word is `RIFF`, `OggS`, `fLaC`, `8BPS` or `Kaydara FBX
410	/// Binary`, and a note opening `GIF89a is the version string…` were each junked
411	/// as media by an unqualified row (measured — see the tests below). The rows
412	/// that use `accept` are exactly the ones carrying a byte text cannot contain:
413	/// `\x89PNG`, `\xff\xd8\xff`, `\x7fELF`, `\x00\x00\x01\x00`, the NUL in
414	/// `II*\x00` / `MM\x00*`, and the `\x01` in the EXR magic.
415	///
416	/// `GIF8` and `BM` were the last two exceptions — printable ASCII taken on
417	/// faith, so a `cars.csv` opening `BMW,model,year` was reported as an image and
418	/// never indexed (#379/#380, the same defect filed twice). The invariant is now
419	/// enforced by walking these rows in
420	/// `printable_magic_tests::every_printable_signature_carries_a_qualifier`, so
421	/// the next row added in violation of it fails a test instead of a code review.
422	///
423	/// Qualifying a magic number is the rule Lucene applies to its own containers:
424	/// `CodecUtil.checkHeader`
425	/// (`lucene/core/src/java/org/apache/lucene/codecs/CodecUtil.java:183-201`,
426	/// Apache-2.0) matches `CODEC_MAGIC` and then hands straight to
427	/// `checkHeaderNoMagic` (`CodecUtil.java:202-246`), which refuses the file
428	/// unless the codec name AND a version inside an accepted range follow — the
429	/// magic alone is never taken as proof. Adapted, not copied: Lucene is
430	/// validating files it wrote itself, this is declining to delete somebody
431	/// else's prose.
432	const MAGIC_TABLE: &[MagicRow] = &[
433	    (b"\x89PNG", "png", accept),
434	    (b"GIF8", "gif", gif_screen_descriptor),
435	    (b"\xff\xd8\xff", "jpeg", accept),
436	    (b"\x7fELF", "elf", accept),
437	    (b"BM", "bmp", bmp_file_header),
438	    (b"\x00\x00\x01\x00", "ico", accept),
439	    (b"8BPS", "psd", psd_version),
440	    (b"II*\x00", "tiff", accept),
441	    (b"MM\x00*", "tiff", accept),
442	    (b"RIFF", "riff", riff_form),
443	    (b"OggS", "ogg", ogg_page),
444	    (b"fLaC", "flac", flac_metadata_block),
445	    (b"ID3", "mp3", id3v2_header),
446	    (b"Kaydara FBX Binary", "fbx", fbx_header),
447	    (b"\x76\x2f\x31\x01", "exr", accept),
448	    // Archives. None is ever opened — see `archive_advice` — but naming the
449	    // kind is what lets the run say "extract it first" instead of "binary
450	    // content (unknown)" about the one file a Google Takeout download consists
451	    // of. Each signature carries a byte text cannot contain (0xBC/0xAF + 0x1C,
452	    // 0x1A + 0x07, 0xFD + NUL), so `accept` is within the invariant above.
453	    (b"7z\xbc\xaf\x27\x1c", "7z", accept),
454	    (b"Rar!\x1a\x07", "rar", accept),
455	    (b"\xfd7zXZ\x00", "xz", accept),
456	];
457	
458	/// Magic-byte signature taken as sufficient on its own.
459	///
460	/// Every caller is a signature containing a byte text cannot contain
461	/// (`\x89PNG`, `\xff\xd8\xff`, `\x7fELF`, `\x00\x00\x01\x00`, the NUL in
462	/// `II*\x00` / `MM\x00*`, the `\x01` in the EXR magic) — that byte, not this
463	/// function, is what makes the match evidence. A signature made only of
464	/// printable ASCII must NOT be routed here; give it a structural qualifier, as
465	/// `GIF8` and `BM` now have (#379/#380). Do not read this function as a proof
466	/// that its callers are safe; it is only a statement that no *further* check is
467	/// performed.
468	fn accept(_prefix: &[u8]) -> bool {
469	    true
470	}
471	
472	/// GIF: `GIF8` on its own is four printable letters, so a note opening "GIF89a
473	/// is the header format used by the GIF image standard" was classified as an
474	/// image and junked by `scan_file` as "binary content (gif)" (#379/#380).
475	///
476	/// Widening the signature to the full six-byte version stamp is NOT enough on
477	/// its own — that same sentence supplies `GIF89a` — and neither is adding the
478	/// canvas dimensions, because " i"/"s " are perfectly good non-zero u16s. The
479	/// qualifier has to reach the fields the spec pins to a fixed value.
480	///
481	/// GIF89a spec §17-19: the 6-byte Header (`GIF87a` or `GIF89a`) is followed by
482	/// the 7-byte Logical Screen Descriptor — canvas width and height
483	/// (little-endian, and an image has both), a packed field whose top bit is the
484	/// Global Colour Table flag and whose low three bits size that table, a
485	/// Background Colour Index, and a Pixel Aspect Ratio. Then comes the Global
486	/// Colour Table itself, `3 * 2^(N+1)` bytes, and after it the first block of
487	/// the data stream. The table is at most 768 bytes, so that first block starts
488	/// at offset 781 at the very latest and is always inside the 8 KiB
489	/// `read_prefix` buffer.
490	///
491	/// That first block is the discriminator. The spec admits exactly three
492	/// introducers there — `0x21` Extension, `0x2C` Image Descriptor, `0x3B`
493	/// Trailer — but the introducer ALONE is not enough, and this is worth
494	/// spelling out because it is what the first attempt at this fix used: all
495	/// three bytes are printable (`!`, `,`, `;`), so "GIF89a header, the six bytes
496	/// at the front of every GIF file" puts a comma exactly there and is junked all
497	/// over again. Measured, along with "GIF89a images! …" and "GIF87a format; …".
498	/// So the block is decoded one step further, into fields prose cannot supply:
499	///
500	///   * after `0x21`, the extension label. The spec defines four — Plain Text
501	///     `0x01`, Graphic Control `0xF9`, Comment `0xFE`, Application `0xFF` —
502	///     three unprintable and the fourth a control character. Three of them also
503	///     pin the first sub-block size; Comment does not, so its chain is walked.
504	///     A chain that outruns the read budget is settled on how it ran out:
505	///     a full buffer means a megabyte of chain held together, a short one means
506	///     the file ended mid-chain.
507	///   * after `0x2C`, a 9-byte Image Descriptor. The frame must be non-empty and
508	///     must fit inside the canvas declared two fields earlier, which four
509	///     little-endian u16s of prose do not.
510	///
511	/// A bare `0x3B` is refused: that is a GIF containing no image at all, it
512	/// appears in no corpus measured, and it carries no pixel data to junk.
513	///
514	/// The fields this check does NOT use are as important, because round 1 of
515	/// #379 used them and they were wrong. Requiring the Pixel Aspect Ratio and
516	/// the Background Colour Index to be zero looks safe — satisfying them takes
517	/// NUL bytes, and prose has no NULs — but it refuses REAL GIFs. Swept over
518	/// every distinct GIF on the build machine (147 files deduped by content hash,
519	/// 51 B to 17.6 MB): the rule below accepts 147/147; the aspect/background rule
520	/// refused 4, among them this repository's own `docs/media/demo.gif`, whose
521	/// aspect byte is 49 — the spec's encoding of a 1:1 pixel ratio, since
522	/// `(49 + 15) / 64 = 1.0`.
523	///
524	/// Falling through to the text heuristics is not a safety net, and the honest
525	/// version of that claim is narrower than "it still classifies binary". All 4
526	/// refused GIFs do still reach `Family::Binary` here, but as `unknown` rather
527	/// than `gif`, and only because their first 8 KiB decodes above the 10%
528	/// control-character threshold — by 0.14 to 1.5 percentage points. Two other
529	/// GIFs in the same 147 sit BELOW it, at 9.39% and 9.78%, and would be
530	/// sectioned into prose records outright if they were refused. Whether a real
531	/// image survives therefore turns on the entropy of its first 8 KiB, which no
532	/// qualifier controls. Pinned by
533	/// `real_gif_shapes_the_aspect_ratio_rule_refused`.
534	fn gif_screen_descriptor(prefix: &[u8]) -> bool {
535	    if prefix.len() < 13 || !matches!(&prefix[..6], b"GIF87a" | b"GIF89a") {
536	        return false;
537	    }
538	    let canvas_width = u16::from_le_bytes([prefix[6], prefix[7]]);
539	    let canvas_height = u16::from_le_bytes([prefix[8], prefix[9]]);
540	    if canvas_width == 0 || canvas_height == 0 {
541	        return false;
542	    }
543	    let packed = prefix[10];
544	    // `3 * 2^(N+1)`, N being the low three bits: 6 bytes at N=0, 768 at N=7.
545	    let color_table = if packed & 0x80 != 0 {
546	        3 * (1usize << ((packed & 0x07) + 1))
547	    } else {
548	        0
549	    };
550	    // Background Colour Index (11) and Pixel Aspect Ratio (12) are skipped on
551	    // purpose — see above, real encoders put non-zero bytes in both.
552	    let block = 13 + color_table;
553	    match prefix.get(block) {
554	        // Extension. The label alone is not a discriminator: `decode()` falls
555	        // back to windows-1252 (see `decode`, below), where 0xF9/0xFE/0xFF are
556	        // ordinary latin-1 letters, so `"GIF89a fichie!" + 0xF9 + French prose`
557	        // satisfied the label check and was junked as an image. The spec pins
558	        // the FIRST sub-block size for three of the four labels, and all three
559	        // sizes are non-printable.
560	        Some(0x21) => match (prefix.get(block + 1), prefix.get(block + 2)) {
561	            (Some(0x01), Some(12)) => true, // Plain Text: 12-byte block
562	            (Some(0xf9), Some(4)) => true,  // Graphic Control: 4-byte block
563	            (Some(0xff), Some(11)) => true, // Application: 11-byte block
564	            // Comment sizes are genuinely variable (1..=255 per sub-block), so
565	            // there is no fixed byte to pin. Walk the sub-block chain instead:
566	            // a real Comment terminates with a 0x00 and is followed by another
567	            // introducer. Prose has to land that whole structure, not one byte.
568	            //
569	            // A zero FIRST size is the empty comment `21 FE 00`, which giflib
570	            // writes for `EGifPutExtensionLeader(0xFE)` + `EGifPutExtensionTrailer`
571	            // and which every decoder here accepts. It used to fall to `_ =>
572	            // false`, which refused all six such files in the corpus even
573	            // though every one of them decodes in both Pillow and giflib.
574	            // The NUL is the evidence: it sits at a derived offset, and
575	            // prose has no NUL to put there — so nothing further is checked,
576	            // and in particular the byte AFTER it is not, because giflib emits
577	            // its zero-length sub-block and its trailer as `21 FE 00 00`.
578	            (Some(0xfe), Some(0)) => true,
579	            (Some(0xfe), Some(_)) => {
580	                // Walk the sub-block chain. Two outcomes are decisive and one
581	                // is not, and conflating them is what broke real GIFs: a
582	                // comment longer than the 8 KiB prefix simply cannot be walked
583	                // to its end here, and "I ran out of buffer" is not evidence
584	                // of text.
585	                let mut at = block + 2;
586	                loop {
587	                    match prefix.get(at) {
588	                        // Terminated inside the prefix: decisive. A real
589	                        // comment is followed by another block. `None` means
590	                        // the terminator is the last byte we hold, which is
591	                        // the prefix edge, not a malformed file.
592	                        Some(0) => {
593	                            return matches!(prefix.get(at + 1), None | Some(0x21 | 0x2c | 0x3b));
594	                        }
595	                        Some(&len) => at += 1 + usize::from(len),
596	                        // Ran out of bytes, and the answer turns on WHY.
597	                        //
598	                        // Be clear about what the walk proves, because the
599	                        // obvious reading is backwards. Its only stop condition
600	                        // is a NUL landing on a hop; every other byte 1..=255 is
601	                        // a legal sub-block size. So "the chain survived" means
602	                        // "no NUL landed on a hop" and nothing else. Text has no
603	                        // NULs, so text survives with probability 1. Measured
604	                        // precisely: 0 of the 265 corpus text negatives contain
605	                        // a NUL anywhere, so no walk over any of them can
606	                        // terminate — which is the property this needs. (Only
607	                        // 10 of the 265 actually reach the walk; the rest fail
608	                        // the header gate first. An earlier draft said "265 of
609	                        // 265 walk a full megabyte", which overstated what was
610	                        // exercised even though the conclusion holds.) High-entropy
611	                        // binary is what the walk rejects: 0 of 200 uniform
612	                        // random megabytes survive, matching
613	                        // (255/256)^(2^20/128.5) = 1.4e-14. It is not even much
614	                        // of a walk — hops average 59 bytes in a prose fixture
615	                        // and 256 in a real commented GIF, so it inspects 1.7%
616	                        // and 0.4% of the buffer respectively.
617	                        //
618	                        // The discriminating is therefore done by the header
619	                        // gate above, not here: `0x21` at `block` and `0xFE`
620	                        // at `block + 1`, where `block = 13 + gct` and `gct` is
621	                        // 0 without a Global Colour Table — so the pair sits at
622	                        // one of 13, 19, 25, 37, 61, 109, 205, 397 or 781, NOT
623	                        // at a fixed offset. What the gate rests on is not that
624	                        // text lacks 0xFE — 43 of the 265 corpus text negatives
625	                        // contain one somewhere — but that text does not carry
626	                        // 0x21 followed by 0xFE at one of those nine computed
627	                        // offsets. An earlier version of this sentence said
628	                        // "0xFE is neither ASCII nor valid UTF-8, which is the
629	                        // part ordinary text lacks", which is the kind of
630	                        // unmeasured universal this comment block exists to
631	                        // stop, written into the sentence explaining the gate.
632	                        // Verified on disk — the same 1 MiB French-prose file
633	                        // with 0x7E in that slot stays TxtProse and with 0xFE
634	                        // becomes binary/gif. All this arm decides is how much
635	                        // text has to accumulate behind that gate before it is
636	                        // admitted — so on THIS path the budget is the rule and
637	                        // the chain is not. Not on the other one: the canvas
638	                        // disjunct below is ungated by size, as the paragraph
639	                        // twenty-five lines down already says.
640	                        //
641	                        // Given that, a FULL buffer answers image. A SHORT one
642	                        // asks the canvas rule from round 4.
643	                        //
644	                        // Be exact about which files that rule sees, because an
645	                        // earlier version of this comment was not. It said the
646	                        // short-buffer arm only judges TRUNCATED files, on the
647	                        // reasoning that a complete GIF terminates its comment.
648	                        // The half about GIFs is true; the half about the
649	                        // population is false, and the file says why thirty
650	                        // lines up: the walk stops only on a NUL, and text has
651	                        // none, so ANY text file that clears the header gate
652	                        // runs its chain to EOF and lands here — at 3 KB as
653	                        // readily as at 3 MB. It is then called an image
654	                        // whenever `prefix[7]` or `prefix[9]` is a byte below
655	                        // 0x20 other than \t, \n or \r — 29 values, not "a
656	                        // control byte": DEL (0x7F) and the C1 range do not
657	                        // trigger it. Measured: the same prose
658	                        // with 0x0B, 0x0C or 0x1B at offset 7 is Binary at
659	                        // 3,000 / 20,000 / 600,000 bytes, and with 0x0A stays
660	                        // TxtProse at all three.
661	                        //
662	                        // So there are two independent paths to "image" and
663	                        // only one of them is size-gated. The cost stated below
664	                        // as "10 corpus text files above the budget" is the
665	                        // full-buffer path's cost alone; the canvas path adds
666	                        // prose with a control byte in a canvas high slot, at
667	                        // any size, and no corpus file exercises it. Two
668	                        // explanations for that have now been wrong, so this
669	                        // one states only what was counted and stops.
670	                        //
671	                        // Of the 264 GIF-magic text negatives, ZERO carry 0x0A
672	                        // at offset 7 or 9, and zero carry any byte below 0x20
673	                        // there. The distribution is 'b' x194 / 'e' x26 at
674	                        // offset 7 and 'd' x180 / 't' x26 at offset 9, and 180
675	                        // of the files carry the literal bytes `abcd` at 6..9 —
676	                        // because the generators splice `filler = a,b,c,d,…`
677	                        // straight after the magic — build_text.py:199 for 140
678	                        // of them, the same line duplicated at build_text2.py:62
679	                        // and :72 for the other 40. So the
680	                        // frequencies are the builder's alphabet, NOT "ordinary
681	                        // prose" as an earlier version of this comment claimed,
682	                        // and certainly not a property of English: the corpus
683	                        // deliberately includes Spanish, French, Russian,
684	                        // Chinese, Greek, Hebrew and Arabic negatives.
685	                        //
686	                        // Every one of these files was generated by
687	                        // build_text.py / build_text2.py, so the builder chose
688	                        // what follows the magic. (An earlier draft added
689	                        // "nothing in real prose opens with GIF magic" here.
690	                        // That is not among what was counted, and this file
691	                        // elsewhere rests on the opposite: the block-introducer
692	                        // arm exists because `"GIF89a header, the six bytes at
693	                        // the front of every GIF file"` is real prose that does.)
694	                        // No fixture family was ever
695	                        // built to put a control byte at 7 or 9, so the corpus
696	                        // has no power to see this path. That is a fact about
697	                        // its construction, and there is no further mechanism
698	                        // to infer.
699	                        //
700	                        // That composition is measured against the budget test
701	                        // alone, not assumed. Identical on every set that
702	                        // matters and strictly better on one:
703	                        //
704	                        //   71 round-5 GIFs           71 Binary   both
705	                        //   674 corpus images        674 Binary   both
706	                        //   265 text negatives       257 text     both
707	                        //   265 inflated past budget  18 Binary   both
708	                        //   13 corpus GIFs cut @8192  13 Binary   vs 2
709	                        //
710	                        // The last row is the reason to keep it: without the
711	                        // canvas fallback 11 of 13 truncated real images go to
712	                        // the prose extractor. A file mid-copy in a watched
713	                        // directory is that shape, and `sniff` runs on live
714	                        // paths (lib.rs:1151, 4258). That is a real gain, paid
715	                        // for with a text cost that has no size floor — the
716	                        // trade, stated whole rather than at its flattering
717	                        // end.
718	                        //
719	                        // Answering image unconditionally on a short buffer
720	                        // instead (round 2's rejected `true`) junks 10 corpus
721	                        // text files — windows-1252 prose carrying `þ` in that
722	                        // slot — so the full-buffer half stays as it is. Pinned
723	                        // by `a_truncated_gif_is_called_an_image_and_that_is_the_trade`,
724	                        // which now asserts Binary.
725	                        None => {
726	                            return prefix.len() >= GIF_PREFIX
727	                                || canvas_dimension_text_cannot_write(prefix)
728	                        }
729	                    }
730	                }
731	            }
732	            _ => false,
733	        },
734	        Some(0x2c) => {
735	            // Image Descriptor: 8 bytes of geometry, then its own packed byte.
736	            let Some(desc) = prefix.get(block + 1..block + 10) else {
737	                return false;
738	            };
739	            let left = u32::from(u16::from_le_bytes([desc[0], desc[1]]));
740	            let top = u32::from(u16::from_le_bytes([desc[2], desc[3]]));
741	            let width = u32::from(u16::from_le_bytes([desc[4], desc[5]]));
742	            let height = u32::from(u16::from_le_bytes([desc[6], desc[7]]));
743	            if width == 0
744	                || height == 0
745	                || left + width > u32::from(canvas_width)
746	                || top + height > u32::from(canvas_height)
747	            {
748	                return false;
749	            }
750	            // Geometry alone is satisfiable by all-ASCII input. For any such
751	            // input `packed & 0x80` is clear, so `block` is always 13, and a
752	            // ',' at offset 13 followed by four little-endian u16s whose HIGH
753	            // bytes (15, 17, 19, 21) are spaces clears every bound above.
754	            // Decode one field further, to the LZW minimum code size that
755	            // opens the image data. A GIF palette holds at most 256 entries, so
756	            // this field is bits-per-pixel and cannot exceed 8 — codes grow to
757	            // 12 bits during compression, but the MINIMUM code size is 2..=8.
758	            // Round 2 wrote 2..=12, and that width is what let text back
759	            // through: 9, 10, 11 and 12 are exactly TAB, LF, VT and FF, so an
760	            // ordinary line break at the derived offset satisfied it. Measured,
761	            // every real image-descriptor-first GIF on the build machine
762	            // carries 8 here across palettes of 2 to 256 entries, while the
763	            // CP1252 and ASCII counterexamples carry 9 or 10.
764	            let has_local_table = desc[8] & 0x80 != 0;
765	            // A frame needs a palette: its own Local Colour Table, or the
766	            // Global one. With neither there is nothing to decode pixels
767	            // against, so such a file is not a GIF at all. This is what
768	            // separates prose whose byte at the LZW position happens to be a
769	            // control character — the CSV counterexample carries `\n` (10),
770	            // which is inside the old 2..=12 range and cleared the check
771	            // below on its own.
772	            if !has_local_table && packed & 0x80 == 0 {
773	                return false;
774	            }
775	            let local_table = if has_local_table {
776	                3 * (1usize << ((desc[8] & 0x07) + 1))
777	            } else {
778	                0
779	            };
780	            matches!(prefix.get(block + 10 + local_table), Some(2..=8))
781	        }
782	        _ => false,
783	    }
784	}
