1608	fn sniff_csv_dialect(nonblank: &[&str]) -> Option<CsvDialect> {
1609	    if nonblank.len() < 2 {
1610	        return None;
1611	    }
1612	    let sample: Vec<&str> = nonblank.iter().take(64).copied().collect();
1613	    let mut best: Option<(u8, usize)> = None; // (delim, field count)
1614	    for delim in *b",;\t|" {
1615	        let counts: Vec<usize> = sample
1616	            .iter()
1617	            .map(|l| split_quoted(l, delim).len())
1618	            .collect();
1619	        let first = counts[0];
1620	        if first < 2 {
1621	            continue;
1622	        }
1623	        let consistent = counts.iter().filter(|&&c| c == first).count();
1624	        // ≥90% of lines share the same field count
1625	        if consistent * 10 >= counts.len() * 9 {
1626	            match best {
1627	                Some((_, bc)) if bc >= first => {}
1628	                _ => best = Some((delim, first)),
1629	            }
1630	        }
1631	    }
1632	    let (delim, _) = best?;
1633	    let head_fields = split_quoted(sample[0], delim);
1634	    let numericish = |s: &str| {
1635	        let t = s.trim();
1636	        !t.is_empty()
1637	            && t.chars()
1638	                .all(|c| c.is_ascii_digit() || matches!(c, '.' | ',' | '-' | '+'))
1639	            && t.chars().any(|c| c.is_ascii_digit())
1640	    };
1641	    let has_header = {
1642	        let mut distinct = std::collections::HashSet::new();
1643	        let all_nonnum = head_fields.iter().all(|f| !numericish(f));
1644	        let all_distinct = head_fields
1645	            .iter()
1646	            .all(|f| distinct.insert(f.trim().to_string()));
1647	        let body_has_num = sample
1648	            .iter()
1649	            .skip(1)
1650	            .any(|l| split_quoted(l, delim).iter().any(|f| numericish(f)));
1651	        all_nonnum && all_distinct && body_has_num
1652	    };
1653	    // decimal comma: with ';' delimiter, a meaningful share of fields look like 12,3
1654	    let decimal_comma = if delim == b';' {
1655	        let re = regex::Regex::new(r"^-?\d{1,9},\d+$").unwrap();
1656	        let (mut num, mut hits) = (0usize, 0usize);
1657	        for l in sample.iter().skip(if has_header { 1 } else { 0 }) {
1658	            for f in split_quoted(l, delim) {
1659	                let t = f.trim().to_string();
1660	                if numericish(&t) {
1661	                    num += 1;
1662	                    if re.is_match(&t) {
1663	                        hits += 1;
1664	                    }
1665	                }
1666	            }
1667	        }
1668	        num > 0 && hits * 10 >= num * 3
1669	    } else {
1670	        false
1671	    };
1672	    Some(CsvDialect {
1673	        delim,
1674	        has_header,
1675	        decimal_comma,
1676	    })
1677	}
