2633	    /// GIF89a, `canvas` px square, 2-entry global colour table, then a Comment
2634	    /// Extension whose sub-blocks are `sizes` cycled until the chain outruns
2635	    /// the GIF read budget. Returns exactly what `read_prefix` would hand
2636	    /// `sniff_bytes` for such a file — `GIF_PREFIX` bytes and no more.
2637	    fn streamed_comment_prefix(canvas: u16, sizes: &[u8]) -> Vec<u8> {
2638	        let mut g: Vec<u8> = b"GIF89a".to_vec();
2639	        g.extend_from_slice(&canvas.to_le_bytes());
2640	        g.extend_from_slice(&canvas.to_le_bytes());
2641	        g.push(0x80); // GCT present, 2 entries
2642	        g.push(0);
2643	        g.push(0);
2644	        g.extend_from_slice(&[0, 0, 0, 0xff, 0xff, 0xff]); // GCT
2645	        g.extend_from_slice(&[0x21, 0xfe]); // Comment Extension
2646	        for &n in sizes.iter().cycle() {
2647	            if g.len() > GIF_PREFIX + 512 {
2648	                break;
2649	            }
2650	            g.push(n);
2651	            g.extend(std::iter::repeat_n(b'D', usize::from(n)));
2652	        }
2653	        g.truncate(GIF_PREFIX);
2654	        g
2655	    }
