2657	    /// Round 3's rule — "a chain that outruns the prefix is an image only if
2658	    /// every sub-block size seen is 0xFF" — measured against the ground-truth
2659	    /// corpus (939 files; 674 images, each decode-checked with Pillow AND
2660	    /// giflib `DGifSlurp`; 265 text files). It refuses 43 of the 92 images that
2661	    /// reach this arm, and 37 of those are sectioned into prose: 2,524 junk
2662	    /// records out of two and a half real image files.
2663	    ///
2664	    /// The premise is simply not how the encoders write. giflib's streaming
2665	    /// API emits one sub-block per `EGifPutExtensionBlock` call, at the length
2666	    /// the CALLER passed, so the corpus holds chains of 1, 2, 16, 32, 64, 100,
2667	    /// 120, 127, 128, 192, 200 and 250..=254 — `gstream_long_sz064_x160.gif`,
2668	    /// `prior_*_c001.gif` … `prior_*_c254.gif`. ImageMagick writes a first
2669	    /// sub-block at N and the rest at N-1 (`prior_*_imagick_im20k_w200.gif`:
2670	    /// 200, 199, 199, …). Splicing produces alternating 255/10 and 20-then-255
2671	    /// chains. Every size in `1..=255` is legal and all of these decode in both
2672	    /// decoders.
2673	    ///
2674	    /// The sizes below are the ones actually on disk in that corpus, not a
2675	    /// sweep invented here.
2676	    #[test]
2677	    fn a_streamed_comment_chain_is_not_packed_to_255() {
2678	        for (label, sizes) in [
2679	            ("giflib-stream-1", &[1u8][..]),
2680	            ("giflib-stream-2", &[2][..]),
2681	            ("giflib-stream-16", &[16][..]),
2682	            ("giflib-stream-32", &[32][..]),
2683	            ("giflib-stream-64", &[64][..]),
2684	            ("giflib-stream-100", &[100][..]),
2685	            ("giflib-stream-127", &[127][..]),
2686	            ("giflib-stream-128", &[128][..]),
2687	            ("giflib-stream-192", &[192][..]),
2688	            ("giflib-stream-250", &[250][..]),
2689	            ("giflib-stream-254", &[254][..]),
2690	            ("giflib-stream-255", &[255][..]),
2691	            ("imagemagick-200-then-199", &[200, 199, 199, 199][..]),
2692	            ("imagemagick-60-then-59", &[60, 59, 59, 59][..]),
2693	            ("spliced-255-then-10", &[255, 10][..]),
2694	            ("spliced-20-then-255", &[20, 255, 255, 255][..]),
2695	        ] {
2696	            let prefix = streamed_comment_prefix(48, sizes);
2697	            assert_eq!(
2698	                prefix.len(),
2699	                GIF_PREFIX,
2700	                "{label}: fixture must fill the GIF read budget"
2701	            );
2702	            let p = Path::new("frame.gif");
2703	            let sn = sniff_bytes(&prefix, p, p, false).unwrap();
2704	            assert_eq!(
2705	                (sn.family, sn.binary_kind.as_deref()),
2706	                (Family::Binary, Some("gif")),
2707	                "{label}: a real GIF whose comment sub-blocks are not 255 was \
2708	                 refused and handed to the prose extractor — #379 inverted, and \
2709	                 the shape 100% of the real commented GIFs on this machine have"
2710	            );
2711	        }
2712	    }
