2714	    /// The empty Comment Extension, `21 FE 00`. giflib writes it whenever a
2715	    /// caller opens a comment and closes it without content
2716	    /// (`EGifPutExtensionLeader(0xFE)` then `EGifPutExtensionTrailer`), and the
2717	    /// corpus holds six such files — all six decode in Pillow AND giflib, and
2718	    /// all six were refused, because the arm's guard was `first != 0` and a
2719	    /// zero first size fell through to `_ => false`.
2720	    ///
2721	    /// Both on-disk shapes are here. `21 FE 00 2C` is the plain one;
2722	    /// `21 FE 00 00 2C` is giflib emitting a zero-length sub-block AND its
2723	    /// trailer, which is why the byte after the terminator is not checked.
2724	    #[test]
2725	    fn an_empty_comment_extension_is_still_a_gif() {
2726	        fn empty_comment_gif(tail: &[u8]) -> Vec<u8> {
2727	            let mut g: Vec<u8> = b"GIF89a".to_vec();
2728	            g.extend_from_slice(&8u16.to_le_bytes());
2729	            g.extend_from_slice(&8u16.to_le_bytes());
2730	            g.push(0x80);
2731	            g.push(0);
2732	            g.push(0);
2733	            g.extend_from_slice(&[0, 0, 0, 0xff, 0xff, 0xff]); // GCT
2734	            g.extend_from_slice(&[0x21, 0xfe, 0x00]); // empty comment
2735	            g.extend_from_slice(tail);
2736	            g
2737	        }
2738	        for (label, tail) in [
2739	            (
2740	                "21-fe-00-then-image",
2741	                &[0x2c, 0, 0, 0, 0, 8, 0, 8, 0, 0, 0x02][..],
2742	            ),
2743	            (
2744	                "21-fe-00-00-then-image",
2745	                &[0x00, 0x2c, 0, 0, 0, 0, 8, 0, 8, 0, 0, 0x02][..],
2746	            ),
2747	            ("21-fe-00-then-trailer", &[0x3b][..]),
2748	        ] {
2749	            let bytes = empty_comment_gif(tail);
2750	            let p = Path::new("empty.gif");
2751	            let sn = sniff_bytes(&bytes, p, p, false).unwrap();
2752	            assert_eq!(
2753	                (sn.family, sn.binary_kind.as_deref()),
2754	                (Family::Binary, Some("gif")),
2755	                "{label}: a decodable GIF carrying an empty comment was refused"
2756	            );
2757	        }
2758	    }
