2760	    /// The tie-break for an outrunning chain is the canvas, and this is the
2761	    /// fixture that decides HOW it is read. The obvious form — "a canvas
2762	    /// dimension below 8192, which printable ASCII cannot declare" — is
2763	    /// forgeable, because `\t`, `\n` and `\r` are bytes below 0x20 that text
2764	    /// carries all the time: a newline at offset 7 declares a 2680 px width.
2765	    /// Measured through the real `sniff()`: with the bare `< 8192` test these
2766	    /// two files classify `binary (gif)`; with `\t\n\r` excluded they stay
2767	    /// `TxtProse`, which is what they are.
2768	    #[test]
2769	    fn prose_with_a_newline_in_the_canvas_is_not_a_gif() {
2770	        for (label, seven) in [("newline", b'\n'), ("tab", b'\t'), ("cr", b'\r')] {
2771	            let mut prose: Vec<u8> = b"GIF89ax".to_vec(); // 0..=6
2772	            prose.push(seven); // 7: canvas width high byte
2773	            prose.extend_from_slice(b"yze"); // 8,9 height; 10 packed (GCT clear)
2774	            prose.extend_from_slice(b"st"); // 11 background, 12 aspect
2775	            prose.push(b'!'); // 13: Extension introducer
2776	            prose.push(0xfe); // 14: Comment label
2777	            prose.push(b'L'); // 15: first sub-block size, 76
2778	            for _ in 0..400 {
2779	                prose.extend_from_slice(
2780	                    "Le format GIF est tres ancien et reste partout sur le web. ".as_bytes(),
2781	                );
2782	            }
2783	            prose.truncate(8192);
2784	            let p = Path::new("notes.txt");
2785	            let sn = sniff_bytes(&prose, p, p, false).unwrap();
2786	            assert_eq!(
2787	                sn.family,
2788	                Family::TxtProse,
2789	                "{label}: prose was junked as {:?} — this file ends mid-chain, \
2790	                 which is what a text file does and a GIF does not",
2791	                sn.binary_kind
2792	            );
2793	        }
2794	    }
