2796	    /// A truncated GIF is still called an image, by the canvas fallback.
2797	    ///
2798	    /// Deliberate, and the reasoning is not that this is harmless. The cost is
2799	    /// paid in the other direction: the canvas disjunct calls a text file an
2800	    /// image whenever it carries the header shape and a sub-0x20 byte at
2801	    /// offset 7 or 9, at any size, which is what
2802	    /// `the_canvas_path_junks_prose_at_any_size_and_the_budget_does_not_bound_it`
2803	    /// pins. That is a good file dropped, and a dropped good file is never
2804	    /// noticed.
2805	    ///
2806	    /// HISTORICAL, and kept because it is the reasoning that lost. Between
2807	    /// `0e5d740` and `12b4a4e` the arm was `prefix.len() >= GIF_PREFIX` alone,
2808	    /// and this paragraph read: "A cut real GIF goes to the prose extractor and
2809	    /// is sectioned into junk records — exactly the harm #379 and #427 were
2810	    /// fighting, with the sign flipped. It is preferred anyway because a
2811	    /// truncated GIF is a broken file that no decoder accepts, while the
2812	    /// alternative (answer "image" on a short buffer, round 2's rejected
2813	    /// `true`) silently drops 10 good corpus text files."
2814	    ///
2815	    /// `12b4a4e` restored the canvas disjunct and inverted that answer. It
2816	    /// changed this doc's summary line and the assertion below from
2817	    /// `Family::TxtProse` to `Family::Binary`, and left the paragraph in place,
2818	    /// describing a rule that no longer existed — through four commits and
2819	    /// seven reviews, including the round that rewrote the identical paragraph
2820	    /// twenty lines above the arm and did not look for its copies.
2821	    ///
2822	    /// The 8192 case is here because the fixtures that used to cover it were
2823	    /// retargeted to `GIF_PREFIX`: a GIF-magic file of exactly 8 KiB still
2824	    /// reaches `sniff_bytes` with an 8192-byte prefix, and the answer for that
2825	    /// state inverted in this change.
2826	    #[test]
2827	    fn a_truncated_gif_is_called_an_image_and_that_is_the_trade() {
2828	        /// A real-shaped commented GIF, then cut.
2829	        fn commented_gif(total: usize) -> Vec<u8> {
2830	            let mut g: Vec<u8> = b"GIF89a".to_vec();
2831	            g.extend_from_slice(&1920u16.to_le_bytes());
2832	            g.extend_from_slice(&1080u16.to_le_bytes());
2833	            g.push(0x80);
2834	            g.push(0);
2835	            g.push(0);
2836	            g.extend_from_slice(&[0, 0, 0, 0xff, 0xff, 0xff]);
2837	            g.extend_from_slice(&[0x21, 0xfe]);
2838	            while g.len() < total {
2839	                g.push(255);
2840	                g.extend(std::iter::repeat_n(b'D', 255));
2841	            }
2842	            g.truncate(total);
2843	            g
2844	        }
2845	
2846	        let p = Path::new("cut.gif");
2847	        for cut in [8192usize, 300_000, 700_000, GIF_PREFIX - 1] {
2848	            let sn = sniff_bytes(&commented_gif(cut), p, p, false).unwrap();
2849	            assert_eq!(
2850	                sn.family,
2851	                Family::Binary,
2852	                "a GIF cut to {cut} B must still read as an image: the chain ran \
2853	                 past EOF, which a complete GIF cannot do, and the canvas then \
2854	                 settles it. This asserted TxtProse for three commits \
2855	                 (0e5d740, d778f70, cf60b65), which sent 11 of 13 truncated \
2856	                 corpus images to the prose extractor"
2857	            );
2858	        }
2859	    }
