2861	    /// The canvas path's cost, which has NO size floor.
2862	    ///
2863	    /// Without this test nothing pins that path at all: the two budget tests
2864	    /// below put `\n` at offset 7, which `canvas_dimension_text_cannot_write`
2865	    /// excludes, so the canvas rule never fires for them. That is an accident
2866	    /// of those fixtures, not a property of the rule.
2867	    ///
2868	    /// Both slots are exercised. The rule is `prefix[7] || prefix[9]`, and a
2869	    /// test varying only one would let a future edit drop the other half
2870	    /// without failing anything.
2871	    #[test]
2872	    fn the_canvas_path_junks_prose_at_any_size_and_the_budget_does_not_bound_it() {
2873	        let p = Path::new("notes.txt");
2874	        // `slot` is 7 or 9 — the two canvas high bytes the rule reads. Varying
2875	        // only one would let a future edit drop the other half of the
2876	        // disjunction without failing anything.
2877	        let build = |slot: usize, high: u8, size: usize| {
2878	            let mut v: Vec<u8> = b"GIF89axyyzest".to_vec();
2879	            v[slot] = high;
2880	            v.push(b'!');
2881	            v.push(0xfe);
2882	            v.push(b'L');
2883	            while v.len() < size {
2884	                v.extend_from_slice("Le format GIF reste partout sur le web. ".as_bytes());
2885	            }
2886	            v.truncate(size);
2887	            v
2888	        };
2889	        for size in [3_000usize, 20_000, 600_000] {
2890	            for slot in [7usize, 9] {
2891	                for high in [0x0bu8, 0x0c, 0x1b] {
2892	                    assert_eq!(
2893	                        sniff_bytes(&build(slot, high, size), p, p, false)
2894	                            .unwrap()
2895	                            .family,
2896	                        Family::Binary,
2897	                        "prose with {high:#04x} at offset {slot} must be called an \
2898	                         image at {size} bytes: the canvas path has no size floor, \
2899	                         so any statement of this rule's cost that says \"above \
2900	                         the budget\" describes only the other half"
2901	                    );
2902	                }
2903	                assert_eq!(
2904	                    sniff_bytes(&build(slot, b'\n', size), p, p, false)
2905	                        .unwrap()
2906	                        .family,
2907	                    Family::TxtProse,
2908	                    "\\n at offset {slot} must stay text: it is excluded from the \
2909	                     canvas rule, and that exclusion is the only reason the two \
2910	                     budget tests below reach the path they claim to bound"
2911	                );
2912	                assert_eq!(
2913	                    sniff_bytes(&build(slot, 0x7f, size), p, p, false)
2914	                        .unwrap()
2915	                        .family,
2916	                    Family::TxtProse,
2917	                    "0x7F must stay text at offset {slot}: the rule is \"below \
2918	                     0x20\", not \"a control byte\", and DEL is a control byte"
2919	                );
2920	            }
2921	        }
2922	    }
