2924	    /// `GIF_PREFIX` bounds the FULL-buffer path, so pin it to a fixed byte
2925	    /// count rather than to itself — without this, `>= 300_000` passes the
2926	    /// suite.
2927	    ///
2928	    /// It is not "the whole rule". `full || canvas` has two independent paths
2929	    /// to "image" and only this one is size-gated; the canvas path is pinned by
2930	    /// `the_canvas_path_junks_prose_at_any_size_and_the_budget_does_not_bound_it`.
2931	    /// This fixture reaches the budget path only because `\n` at offset 7 keeps
2932	    /// it off the canvas path, which is an accident of the fixture — written
2933	    /// down so the next person to widen the text cost does not read this test
2934	    /// as a safety net it is not.
2935	    #[test]
2936	    fn the_budget_is_the_threshold_it_claims() {
2937	        let mut prose: Vec<u8> = b"GIF89ax".to_vec();
2938	        prose.push(b'\n');
2939	        prose.extend_from_slice(b"yzest");
2940	        prose.push(b'!');
2941	        prose.push(0xfe);
2942	        prose.push(b'L');
2943	        while prose.len() < 1_100_000 {
2944	            prose.extend_from_slice("Le format GIF reste partout sur le web. ".as_bytes());
2945	        }
2946	        let p = Path::new("notes.txt");
2947	
2948	        // 600 KB is over any plausible lowered budget and under this one. If a
2949	        // future change shrinks GIF_PREFIX below this, this file — ordinary
2950	        // windows-1252 prose — starts being indexed as an image.
2951	        let six_hundred_k: Vec<u8> = prose.iter().copied().take(600_000).collect();
2952	        assert_eq!(
2953	            sniff_bytes(&six_hundred_k, p, p, false).unwrap().family,
2954	            Family::TxtProse,
2955	            "600 KB of prose must not be called an image; lowering GIF_PREFIX \
2956	             below 600 KB is what would do it"
2957	        );
