/// Build a frontmatter-shaped sniff input whose body is an alias bomb,
/// padded with comment lines so the body is majority NON-`key:`-shaped
/// (the gate `yaml_like_count(body) * 2 < body.len()` in sniff.rs).
fn build(total_budget: usize, fan: usize, width: usize) -> String {
    let mut s = String::from("---\ntitle: p\nowner: p\n---\n");
    // padding comment lines: not `key:`-shaped, ignored by the YAML parser
    loop {
        let line = "# padding comment line to make the body majority non-yaml-like\n";
        if s.len() + line.len() + 600 > total_budget { break; }
        s.push_str(line);
    }
    s.push_str(&format!("a0: &a0 [{}]\n", vec!["lol"; width].join(",")));
    let mut prev = "a0".to_string();
    let mut i = 1usize;
    loop {
        let line = format!("a{i}: &a{i} [{}]\n", vec![format!("*{prev}")].join(","));
        // emulate fan by repeating
        let line = format!("a{i}: &a{i} [{}]\n", std::iter::repeat_n(format!("*{prev}"), fan).collect::<Vec<_>>().join(","));
