/// # Returns
///
/// - None if the file is not encrypted with AES
#[cfg(feature = "aes-crypto")]
pub fn get_aes_verification_key_and_salt(
    &mut self,
    file_number: usize,
) -> ZipResult<Option<AesInfo>> {
    let (_, data) = self
        .shared
        .files
        .get_index(file_number)
