//! TEMPORARY security-audit probe - deleted after the audit run.
use std::time::Instant;

fn peak_rss_mib() -> u64 {
    std::fs::read_to_string("/proc/self/status")
        .unwrap()
        .lines()
        .find(|l| l.starts_with("VmHWM"))
        .unwrap()
        .split_whitespace()
        .nth(1)
        .unwrap()
        .parse::<u64>()
        .unwrap()
        / 1024
}

fn write_tmp(name: &str, bytes: &[u8]) -> std::path::PathBuf {
    let p = std::env::temp_dir().join(name);
    std::fs::write(&p, bytes).unwrap();
    p
}

/// Frontmatter-shaped file whose BODY is a YAML alias bomb, padded with
/// comment lines so the body is majority non-`key:`-shaped.
fn yaml_bomb(total: usize, fan: usize, width: usize, pad: usize) -> Vec<u8> {
    let mut s = String::from("---\ntitle: p\nowner: p\n---\n");
    for i in 0..pad {
        s.push_str(&format!("# padding comment line {i}\n"));
    }
    s.push_str(&format!("a0: &a0 [{}]\n", vec!["lol"; width].join(",")));
